/* TRX-RS 44.1 kHz render (trxrs_render_block_44k1), hand-written SHARC+.
 * Generated by gen_trxrs.py.
 *
 * Bit-exact replacement for the translated render of the original OS 1.63
 * DSP56300 code at P:$101acd-$101b9f (model: trxrs_model.py). It keeps the
 * translated voice layout and the shared scratch contract: every word of
 * voice state, x/y scratch, y:$20 history and the 44.1 kHz block ends as
 * the original leaves it.
 *
 *  1. Sine oscillator (phase Yb:Yc masked to $7fff before each read, step
 *     Y2 * 2^19; lo kept << 8 so the add carries), clip with ramp (Y3, Ya,
 *     Y4), gain Y5 into x:k.
 *  2. Click (source words at $101ba0 + Y8 while Y8 < $300, else a zero
 *     word), envelope Y9 (decay Y1) into x:$60+k; f(n) to @TMP@.
 *  3. Biquad pair with full-precision accumulators A and B, each passing
 *     through MRF as A * 2^8 for its products (they cannot pass 2^55 within
 *     a block, so the 56-bit accumulators never wrap); the l: stores limit
 *     to 48 bits.
 *  4. Block = lim(2*x:$20+k).
 *
 * Declines (calls the reference render) when Y8 < 0 or a coefficient table
 * address is outside the source words.
 *
 * Calling convention as the translated renders: R4 = voice, R8 = sine.
 * @SRC@ = byte address of source word 0 (immutable source base - 0x80000).
 * @TMP@ = a 256-word scratch block owned by the hand-written renders.
 */
.EXTERN md_shared_scratch_x.;
.EXTERN md_shared_scratch_y.;
.EXTERN md_shared_y20.;
.EXTERN trxrs_render_block_44k1_c.;
.SECTION/SW seg_swco;
.GLOBAL trxrs_render_block_44k1.;
trxrs_render_block_44k1.:
    I7=MODIFY (I7,-0x34)(NW);
    DM (-3,I6) = R8;
    DM (-4,I6) = R9;
    DM (-5,I6) = R10;
    DM (-6,I6) = R11;
    DM (-7,I6) = R12;
    DM (-8,I6) = R13;
    DM (-9,I6) = R14;
    DM (-10,I6) = R15;
    R0 = I0;
    DM (-11,I6) = R0;
    R0 = I1;
    DM (-12,I6) = R0;
    R0 = I2;
    DM (-13,I6) = R0;
    R0 = I3;
    DM (-14,I6) = R0;
    R0 = I4;
    DM (-15,I6) = R0;
    R0 = I5;
    DM (-16,I6) = R0;
    R0 = M4;
    DM (-17,I6) = R0;
    R0 = M0;
    DM (-18,I6) = R0;
    R0 = M1;
    DM (-19,I6) = R0;
    R0 = M2;
    DM (-20,I6) = R0;
    R0 = M3;
    DM (-21,I6) = R0;
    R0 = MR0F;
    DM (-22,I6) = R0;
    R0 = MR1F;
    DM (-23,I6) = R0;
    R0 = MR2F;
    DM (-24,I6) = R0;
    DM (-28,I6) = R8;
    R0 = L0;
    DM (-46,I6) = R0;
    R0 = L1;
    DM (-47,I6) = R0;
    R0 = L2;
    DM (-48,I6) = R0;
    R0 = L3;
    DM (-49,I6) = R0;
    R0 = L4;
    DM (-50,I6) = R0;
    R0 = L5;
    DM (-51,I6) = R0;
    R0 = 0;
    L0 = R0;
    L1 = R0;
    L2 = R0;
    L3 = R0;
    L4 = R0;
    L5 = R0;
    I0 = R4;
    R14 = 0x7FFFFF;
    R15 = 0xFF800000;
    R13 = @SRC@;
/* ---- guards: nothing is written before these pass ---------------------- */
    R0 = DM (8,I0);
    R0 = PASS R0;
    IF LT JUMP .L_decline;
    /* biquad coefficients -> @TMP@[4j..] */
    I2 = @TMP@;
    R7 = -7;
    R6 = -8;
    R9 = DM (6,I0);
    R10 = DM (7,I0);
    NOP;
    NOP;
    /* (inlined .L_coef) */
    R1 = 0x140000;
    R1 = R1 + R10;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R4 = DM (0,I4);
    R1 = 0x140080;
    R1 = R1 + R10;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R5 = DM (0,I4);
    R4 = R4 + R9;
    R5 = R5 + R9;
    R1 = 0x140900;
    R1 = R1 + R4;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R11 = DM (0,I4);
    R1 = 0x141900;
    R1 = R1 + R5;
    R1 = FEXT R1 BY 0:24;
    R2 = 0x20000;
    R2 = R1 - R2;
    R3 = 0x1E0000;
    COMPU (R2,R3);
    IF GE JUMP .L_coef_bad_i1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I4 = R1;
    R12 = DM (0,I4);
    R11 = LSHIFT R11 BY 8;
    R12 = LSHIFT R12 BY 8;
    JUMP .L_coef_ret_i1 (DB);
    R0 = R0 - R0;
    NOP;
.L_coef_bad_i1:
    JUMP .L_coef_ret_i1 (DB);
    R0 = -1;
    NOP;
.L_coef_ret_i1:
    R0 = PASS R0;
    IF NE JUMP .L_decline;
    R1 = ASHIFT R11 BY R7;               /* 2*x1 */
    R2 = R12 * R1 (SSF);                 /* floor(4*x1*y1 / 2^24) */
    R3 = 0x400000;
    R2 = R2 - R3;                        /* asl G - 1/2 */
    R2 = MIN(R2,R14);
    R2 = MAX(R2,R15);                    /* g */
    R3 = ASHIFT R12 BY R6;               /* y1 */
    R5 = 0;
    MR1F = R5;
    MR0F = R5;                           /* MR = 0 (no MRF = 0 in the translated forms) */
    MRF = MRF - R12 * R3 (SSF);
    MRF = MRF - R12 * R3 (SSF);          /* asl C */
    R4 = MR1F;                           /* c = lim(-4*y1*y1) */
    R4 = MAX(R4,R15);
    R5 = LSHIFT R4 BY 8;
    DM (0,I2) = R5;
    R5 = LSHIFT R2 BY 8;
    DM (1,I2) = R5;
    DM (2,I2) = R4;
    DM (3,I2) = R2;
    JUMP .L_body;

    /* R9 = sel, R10 = idx: R11 = x1 << 8 = x:(sel + x:($140000+idx) + $140900),
     * R12 = y1 << 8 = x:(sel + x:($140080+idx) + $141900); R0 = 0, or -1 when
     * an address is outside the source words */

/* ---- body ----------------------------------------------------------------- */
.L_body:
    /* y:$20 history: y:$20 = y20 at entry, y20 = u24(y:$20) at exit */
    I1 = md_shared_y20.;
    R1 = DM (0,I1);
    R1 = FEXT R1 BY 0:24;
    DM (0,I1) = R1;
    R1 = LSHIFT R1 BY 8;
    R6 = -8;
    R1 = ASHIFT R1 BY R6;
    I1 = md_shared_scratch_y.;
    DM (32,I1) = R1;
/* ---- 1. oscillator, clip, gain into x:k --------------------------------- */
    R0 = DM (-28,I6);
    I4 = R0;                            /* sine table */
    R0 = DM (2,I0);
    R3 = LSHIFT R0 BY 27;               /* step lo << 8 */
    R12 = -5;
    R4 = ASHIFT R0 BY R12;              /* step hi */
    R1 = DM (0xB,I0);
    R2 = DM (0xC,I0);
    R2 = LSHIFT R2 BY 8;
    R5 = 0x7FFF;
    R6 = DM (3,I0);                     /* threshold */
    R7 = DM (0xA,I0);                   /* ramp b */
    R8 = DM (4,I0);
    R9 = 0x7EB852;
    R10 = -0x7EB852;
    R11 = DM (5,I0);
    R11 = LSHIFT R11 BY 8;
    R12 = -8;
    I1 = md_shared_scratch_x.;
    LCNTR = 0x20 , DO (PC,.L_osc_end)UNTIL LCE;
    R1 = R1 AND R5;
    M4 = R1;
    R0 = DM (M4,I4);
    R2 = R2 + R3;
    R1 = R1 + R4 + CI;
    R0 = LSHIFT R0 BY 8;
    R0 = ASHIFT R0 BY R12;
    COMP (R0,R6);
    IF GE JUMP .L_clip_hi;
    R13 = -R0;
    COMP (R13,R6);
    IF GE JUMP .L_clip_lo;
    R7 = R7 - R7;
    JUMP .L_gain;
.L_clip_hi:
    R0 = R9 - R7;
    R7 = R7 + R8;
    R0 = MIN(R0,R14);
    JUMP .L_gain (DB);
    R0 = MAX(R0,R15);
    NOP;
.L_clip_lo:
    R0 = R10 + R7;
    R7 = R7 + R8;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
.L_gain:
    R0 = R0 * R11 (SSF);
    R0 = MIN(R0,R14);
.L_osc_end:
    DM (I1,M6) = R0;
    R1 = LSHIFT R1 BY 8;
    R1 = ASHIFT R1 BY R12;
    DM (0xB,I0) = R1;
    R2 = ASHIFT R2 BY R12;
    DM (0xC,I0) = R2;
    R7 = MIN(R7,R14);
    R7 = MAX(R7,R15);
    DM (0xA,I0) = R7;

/* ---- 2. click and envelope into x:$60+k; f(n) to @TMP@ ------------------- */
    R13 = @SRC@;
    I5 = @TMP@;
    I5=MODIFY (I5,0x10)(NW);
    R0 = 0;
    DM (0,I5) = R0;
    M2 = 0;
    R0 = DM (8,I0);
    R1 = 0x300;
    COMP (R0,R1);
    IF GE JUMP .L_noclick;
    R1 = 0x101BA0;
    R1 = R0 + R1;
    R1 = LSHIFT R1 BY 2;
    R1 = R1 + R13;
    I5 = R1;
    M2 = 1;
    R1 = 0x20;
    R0 = R0 + R1;
    DM (8,I0) = R0;
.L_noclick:
    R1 = DM (9,I0);                     /* env x1 */
    R2 = DM (1,I0);
    R2 = LSHIFT R2 BY 8;
    R3 = DM (0x11,I0);                  /* x(-1) */
    R0 = DM (0x12,I0);
    R4 = R3 - R0;                       /* d(-1) */
    R12 = -8;
    I1 = md_shared_scratch_x.;
    I2 = md_shared_scratch_x.;
    I2=MODIFY (I2,0x60)(NW);
    I3 = @TMP@;
    I3=MODIFY (I3,0x20)(NW);
    LCNTR = 0x20 , DO (PC,.L_env_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R5 = DM (I5,M2);
    R5 = LSHIFT R5 BY 8;
    R5 = ASHIFT R5 BY R12;
    R0 = R0 + R5;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
    R6 = LSHIFT R1 BY 8;
    R0 = R0 * R6 (SSF);
    R0 = MIN(R0,R14);
    R1 = R1 * R2 (SSF) , DM (I2,M6) = R0;
    R1 = MIN(R1,R14);
    R5 = R0 - R3;                       /* d(n) */
    R3 = PASS R0;
    R6 = R5 - R4;
    R4 = PASS R5;
.L_env_end:
    DM (I3,M6) = R6;
    DM (9,I0) = R1;

/* ---- 3. full-precision pair: A += f(n) * 2^23 (s), B += 2c t(n-2) + 4g t(n-1)
 * + (s_raw(n) - 2S(n-1) + S(n-2)) * 2^23; l: stores: S(n) to x:/y:$42 (n even),
 * $43 (n odd), t(n) to x:/y:$22+n; then A += 2c S(n-1) + 4g S(n).
 * Accumulators in the translator's form (mulforms.py): MRF holds A between
 * samples; A goes through registers (R1 = A2:A1, R9 = A0) for its 2^23 term
 * and B through MRF for its products, B kept as A2:A1, A0 in frame words
 * -29/-30. A 2^23 term is an ALU add on the 24-bit low word with its carry
 * (no multiply by a power of two); 2c, 4g products are (c << 8) * word,
 * twice for 4g. Registers (even sample): S(n-1) R4, S(n-2) R5, t(n-1) R6,
 * t(n-2) R7; R11 = c << 8, R12 = g << 8, R13 = -1, R8 = -8. */
    I2 = @TMP@;
    R11 = DM (0,I2);
    R12 = DM (1,I2);
    R13 = -1;
    R8 = -8;
    I1 = md_shared_scratch_x.;
    R0 = DM (0xE,I0);
    DM (0x42,I1) = R0;
    R0 = DM (0xD,I0);
    DM (0x43,I1) = R0;
    R0 = DM (0x10,I0);
    DM (0x20,I1) = R0;
    R0 = DM (0xF,I0);
    DM (0x21,I1) = R0;
    R0 = DM (0x12,I0);
    DM (0x5E,I1) = R0;
    R0 = DM (0x11,I0);
    DM (0x5F,I1) = R0;
    /* y:0..3 = c, 1/2, -1, 1/2 */
    I3 = md_shared_scratch_y.;
    R0 = DM (2,I2);
    DM (0,I3) = R0;
    R0 = 0x400000;
    DM (1,I3) = R0;
    DM (3,I3) = R0;
    DM (2,I3) = R15;
    R4 = DM (0xD,I0);                   /* S(-1) */
    R5 = DM (0xE,I0);                   /* S(-2) */
    R6 = DM (0xF,I0);                   /* t(-1) */
    R7 = DM (0x10,I0);                  /* t(-2) */
    MR1F = R4;
    R0 = DM (0x14,I0);
    R0 = LSHIFT R0 BY 8;
    MR0F = R0;                          /* A = S(-1):Y14 */
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R12 * R4 (SSF);
    MRF = MRF + R12 * R4 (SSF);
    DM (-29,I6) = R6;                   /* B = t(-1):Y13 */
    R0 = DM (0x13,I0);
    R0 = FEXT R0 BY 0:24;
    DM (-30,I6) = R0;
    I3 = @TMP@;
    I3=MODIFY (I3,0x20)(NW);
    I4 = md_shared_scratch_x.;
    I4=MODIFY (I4,0x22)(NW);
    I5 = md_shared_scratch_y.;
    I5=MODIFY (I5,0x22)(NW);
    I2 = md_shared_scratch_y.;
    LCNTR = 0x10 , DO (PC,.L_fp_end)UNTIL LCE;
    R1 = MR1F;                          /* A2:A1 */
    R9 = MR0F;
    R9 = FEXT R9 BY 8:24;               /* A0 */
    R0 = DM (I3,M6);
    R10 = LSHIFT R0 BY 23;
    R10 = FEXT R10 BY 0:24;             /* (term & 1) << 23 */
    R9 = R9 + R10;
    R10 = FEXT R9 BY 24:8;            /* carry */
    R9 = FEXT R9 BY 0:24;
    R1 = R1 + R10;
    R0 = ASHIFT R0 BY R13;
    R1 = R1 + R0;
    R2 = LSHIFT R1 BY 8;
    R2 = ASHIFT R2 BY R8;               /* s_raw */
    R10 = MIN(R1,R14);
    R10 = MAX(R10,R15);
    R3 = LSHIFT R9 BY 8;
    R3 = ASHIFT R3 BY R8;
    COMP (R10,R1);
    IF NE R3 = LSHIFT R1 BY -31;
    IF NE R3 = R3 - 1;
    DM (0x42,I1) = R10;
    DM (0x42,I2) = R3;
    R3 = R2 - R4;
    R3 = R3 - R4;
    R3 = R3 + R5;
    R5 = PASS R10 , R0 = DM (-29,I6);
    R2 = DM (-30,I6);
    R10 = LSHIFT R3 BY 23;
    R10 = FEXT R10 BY 0:24;             /* (term & 1) << 23 */
    R2 = R2 + R10;
    R10 = FEXT R2 BY 24:8;            /* carry */
    R2 = FEXT R2 BY 0:24;
    R0 = R0 + R10;
    R3 = ASHIFT R3 BY R13;
    R0 = R0 + R3;
    MR1F = R0;
    R0 = LSHIFT R2 BY 8;
    MR0F = R0;
    MRF = MRF + R11 * R7 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    MRF = MRF + R12 * R6 (SSF);
    R0 = MR1F;                          /* B2:B1 */
    R2 = MR0F;
    R2 = FEXT R2 BY 8:24;               /* B0 */
    DM (-29,I6) = R0;
    DM (-30,I6) = R2;
    R10 = MIN(R0,R14);
    R10 = MAX(R10,R15);
    R3 = LSHIFT R2 BY 8;
    R3 = ASHIFT R3 BY R8;
    COMP (R10,R0);
    IF NE R3 = LSHIFT R0 BY -31;
    IF NE R3 = R3 - 1;
    DM (I4,M6) = R10;
    R7 = PASS R10 , DM (I5,M6) = R3;
    MR1F = R1;
    R0 = LSHIFT R9 BY 8;
    MR0F = R0;
    MRF = MRF + R11 * R4 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    MRF = MRF + R12 * R5 (SSF);
    R1 = MR1F;                          /* A2:A1 */
    R9 = MR0F;
    R9 = FEXT R9 BY 8:24;               /* A0 */
    R0 = DM (I3,M6);
    R10 = LSHIFT R0 BY 23;
    R10 = FEXT R10 BY 0:24;             /* (term & 1) << 23 */
    R9 = R9 + R10;
    R10 = FEXT R9 BY 24:8;            /* carry */
    R9 = FEXT R9 BY 0:24;
    R1 = R1 + R10;
    R0 = ASHIFT R0 BY R13;
    R1 = R1 + R0;
    R2 = LSHIFT R1 BY 8;
    R2 = ASHIFT R2 BY R8;               /* s_raw */
    R10 = MIN(R1,R14);
    R10 = MAX(R10,R15);
    R3 = LSHIFT R9 BY 8;
    R3 = ASHIFT R3 BY R8;
    COMP (R10,R1);
    IF NE R3 = LSHIFT R1 BY -31;
    IF NE R3 = R3 - 1;
    DM (0x43,I1) = R10;
    DM (0x43,I2) = R3;
    R3 = R2 - R5;
    R3 = R3 - R5;
    R3 = R3 + R4;
    R4 = PASS R10 , R0 = DM (-29,I6);
    R2 = DM (-30,I6);
    R10 = LSHIFT R3 BY 23;
    R10 = FEXT R10 BY 0:24;             /* (term & 1) << 23 */
    R2 = R2 + R10;
    R10 = FEXT R2 BY 24:8;            /* carry */
    R2 = FEXT R2 BY 0:24;
    R0 = R0 + R10;
    R3 = ASHIFT R3 BY R13;
    R0 = R0 + R3;
    MR1F = R0;
    R0 = LSHIFT R2 BY 8;
    MR0F = R0;
    MRF = MRF + R11 * R6 (SSF);
    MRF = MRF + R12 * R7 (SSF);
    MRF = MRF + R12 * R7 (SSF);
    R0 = MR1F;                          /* B2:B1 */
    R2 = MR0F;
    R2 = FEXT R2 BY 8:24;               /* B0 */
    DM (-29,I6) = R0;
    DM (-30,I6) = R2;
    R10 = MIN(R0,R14);
    R10 = MAX(R10,R15);
    R3 = LSHIFT R2 BY 8;
    R3 = ASHIFT R3 BY R8;
    COMP (R10,R0);
    IF NE R3 = LSHIFT R0 BY -31;
    IF NE R3 = R3 - 1;
    DM (I4,M6) = R10;
    R6 = PASS R10 , DM (I5,M6) = R3;
    MR1F = R1;
    R0 = LSHIFT R9 BY 8;
    MR0F = R0;
    MRF = MRF + R11 * R5 (SSF);
    MRF = MRF + R12 * R4 (SSF);
.L_fp_end:
    MRF = MRF + R12 * R4 (SSF);
    R0 = DM (0x43,I1);
    DM (0xD,I0) = R0;
    R0 = DM (0x43,I2);
    DM (0x14,I0) = R0;
    R0 = DM (0x42,I1);
    DM (0xE,I0) = R0;
    R0 = DM (0x41,I1);
    DM (0xF,I0) = R0;
    R0 = DM (0x41,I2);
    DM (0x13,I0) = R0;
    R0 = DM (0x40,I1);
    DM (0x10,I0) = R0;
    R0 = DM (0x7F,I1);
    DM (0x11,I0) = R0;
    R0 = DM (0x7E,I1);
    DM (0x12,I0) = R0;
/* ---- 4. block = lim(2*x:$20+k) ------------------------------------------- */
    I1 = md_shared_scratch_x.;
    I1=MODIFY (I1,0x20)(NW);
    I4 = I0;
    I4=MODIFY (I4,0x15)(NW);
    LCNTR = 0x20 , DO (PC,.L_out_end)UNTIL LCE;
    R0 = DM (I1,M6);
    R0 = R0 + R0;
    R0 = MIN(R0,R14);
    R0 = MAX(R0,R15);
.L_out_end:
    DM (I4,M6) = R0;
    JUMP .L_exit;
.L_decline:
    /* tail call: the C reference render runs in this render's place, in
     * its caller's frame (not nested under this one: the audio stack is
     * 509 words) */
    R4 = I0;
    R0 = DM (-11,I6);
    I0 = R0;
    R0 = DM (-12,I6);
    I1 = R0;
    R0 = DM (-13,I6);
    I2 = R0;
    R0 = DM (-14,I6);
    I3 = R0;
    R0 = DM (-15,I6);
    I4 = R0;
    R0 = DM (-16,I6);
    I5 = R0;
    R0 = DM (-17,I6);
    M4 = R0;
    R0 = DM (-18,I6);
    M0 = R0;
    R0 = DM (-19,I6);
    M1 = R0;
    R0 = DM (-20,I6);
    M2 = R0;
    R0 = DM (-21,I6);
    M3 = R0;
    R0 = DM (-23,I6);
    MR1F = R0;
    R0 = DM (-24,I6);
    MR2F = R0;
    R0 = DM (-22,I6);
    MR0F = R0;
    R0 = DM (-46,I6);
